INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chen-han','陈汉','["汉","大汉"]',NULL,NULL,'cn','east_asia',1360,6,NULL,'year',1364,1,NULL,'year',16325,16368,'ochre',NULL,NULL,'陈友谅由徐寿辉部将崛起，控制湖广、江西等地，1360年杀徐寿辉后称帝、国号汉。政权以江州、武昌为中心，与朱元璋争夺长江流域；1363年鄱阳湖战败，陈友谅阵亡，子陈理继位，次年出降，陈汉亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('ming','{"default":"明","periods":[{"name":"吴","start":{"year":1364,"month":2,"day":4,"confidence":"day"},"end":{"year":1368,"month":1,"day":23,"confidence":"day"}},{"name":"明","start":{"year":1368,"month":1,"day":23,"confidence":"day"},"end":{"year":1644,"month":4,"day":25,"confidence":"day"}},{"name":"南明","start":{"year":1644,"month":6,"day":19,"confidence":"day"},"end":{"year":1662,"month":6,"day":1,"confidence":"day"}}]}','["大明","明","吴","西吴","南明"]',NULL,NULL,'cn','east_asia',1364,1,NULL,'year',1662,12,NULL,'year',16368,19955,'ochre',NULL,NULL,'朱元璋参加郭子兴起义军后取得独立兵权，1356年以应天为基地。1363年鄱阳湖之战击败陈友谅，1364年称吴王，1367年平定张士诚并发动北伐；1368年在应天称帝，建立明朝。
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qing','{"default":"清","periods":[{"name":"金","start":{"year":1616,"month":2,"confidence":"month"},"end":{"year":1636,"month":5,"day":14,"confidence":"day"}},{"name":"清","start":{"year":1636,"month":5,"day":15,"confidence":"day"},"end":{"year":1912,"month":2,"confidence":"month"}}]}','["大清","清","金","后金"]','女真/满洲',NULL,'cn','east_asia',1616,2,NULL,'month',1912,2,NULL,'month',19393,22945,'ochre',NULL,NULL,'1616年2月努尔哈赤建后金，1636年改国号大清；1912年2月宣统退位。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-han','韩宋','["宋","小明王"]',NULL,NULL,'cn','east_asia',1355,2,NULL,'year',1366,12,NULL,'month',16261,16403,'ochre',NULL,NULL,'1355年刘福通等在亳州拥立韩林儿，国号宋、年号龙凤，依托北方红巾军展开对元战争。其后迁都汴梁，元军反攻后退守安丰；1363年安丰失陷，朱元璋救出韩林儿、安置于滁州。1366年韩林儿渡江途中溺亡，韩宋结束，死亡经过有异说。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('song-xu','徐宋','["宋","天完"]',NULL,NULL,'cn','east_asia',1351,10,NULL,'year',1360,6,NULL,'month',16221,16325,'ochre',NULL,NULL,'元末红巾军建立的区域政权。徐寿辉1351年在蕲水称帝，后迁都汉阳，势力一度扩展至湖广、江西；国号及政权称谓在史籍中有宋、天完等不同记载。陈友谅掌权并于1360年杀徐寿辉，徐宋由此终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia-ming','明夏','["大夏","夏"]',NULL,NULL,'cn','east_asia',1362,1,NULL,'year',1371,1,NULL,'year',16344,16452,'ochre',NULL,NULL,'明玉珍由徐寿辉部将转而经营四川，1362年在重庆称帝、国号夏，建元天统，以四川为核心并据有周边地区。政权设置官署、学校并实行较轻赋税；明玉珍死后子明升继位，1371年明军攻取重庆，明夏亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yuan','{"default":"元","periods":[{"name":"蒙古帝国","start":{"year":1206,"month":1,"confidence":"year"},"end":{"year":1271,"month":12,"day":18,"confidence":"day"}},{"name":"元","start":{"year":1271,"month":12,"day":18,"confidence":"day"},"end":{"year":1388,"month":11,"confidence":"month"}}]}','["大元","元","蒙元","北元","残元","故元","蒙古帝国","大蒙古国","蒙古汗国"]','蒙古',NULL,'cn','east_asia',1206,1,NULL,'year',1388,11,NULL,'month',14472,16666,'ochre',NULL,NULL,'1206年铁木真称成吉思汗建国；1271年忽必烈定国号大元，中原史语境转入元朝。帝国诸汗国此后分治。
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-zhang','大周','["大周","周"]',NULL,NULL,'cn','east_asia',1354,1,NULL,'year',1367,9,NULL,'month',16248,16412,'ochre',NULL,NULL,'张士诚起兵后于1354年在高邮称诚王、国号周，建元天祐，1356年据平江并以江南为根基。1363年改称吴王；朱元璋军围攻平江，城破后张士诚被俘，政权于1367年覆亡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ayurbarwada','爱育黎拔力八达','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱育黎拔力八达，元仁宗，元武宗之弟，依兄弟间的继承约定即位。其朝恢复科举取士，重用儒臣并调整财政与官制，推动元廷采用较多中原文官制度；身后由子硕德八剌继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元仁宗"}]','圣文钦孝皇帝','仁宗','元仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ayushiridara','爱猷识理达腊','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱猷识理达腊是元顺帝妥懽帖睦尔长子。元亡后在应昌即位，继续以蒙古政权与明对峙，改元宣光；其后由脱古思帖木儿继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/爱猷识理达腊"},{"label":"《元史·顺帝纪》（维基文库）","url":"https://zh.wikisource.org/wiki/元史/卷046"},{"label":"《明史·唐王聿键传》（维基文库）","url":"https://zh.wikisource.org/wiki/明史/卷118"}]',NULL,'昭宗','元昭宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-xueqin','曹雪芹','qing','[]',NULL,NULL,1715,1,NULL,'year',1763,1,NULL,'year','["文学家"]','清代小说家，名霑，字梦阮，号雪芹，出身江宁织造曹氏家族。家道衰落后居北京西郊，晚年创作《红楼梦》；生卒年与小说定稿情况均有不同考说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹雪芹"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-li','陈理','chen-han','[]',NULL,NULL,1351,1,NULL,'year',1408,1,NULL,'year','["皇帝"]','陈友谅次子。父亲在鄱阳湖战死后于武昌继位，改元德寿；朱元璋次年亲征，陈理出降，陈汉政权告终，后被封归德侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈理_(元末)"}]',NULL,NULL,'陈汉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-youliang','陈友谅','chen-han','[]',NULL,NULL,1320,1,NULL,'year',1363,1,NULL,'year','["皇帝"]','湖北沔阳人，原为徐寿辉部将，1357年杀倪文俊并兼并其军，逐渐控制江西、湖广。1359年挟徐寿辉迁江州、自称汉王，1360年在采石杀徐寿辉后称帝，国号汉，以江州为都，后迁武昌。与朱元璋争夺长江中游，1363年鄱阳湖之战中流矢身亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈友谅"}]',NULL,NULL,'陈汉帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ci-an','慈安','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇太后","政治家"]','钮祜禄氏，咸丰帝皇后；辛酉政变后与慈禧共同垂帘听政；政变后与慈禧共同辅佐同治、光绪两朝；史料对她去世原因有不同解释。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慈安"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ci-xi','慈禧','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇太后","政治家"]','叶赫那拉氏，咸丰帝妃、同治帝生母，与恭亲王奕訢发动辛酉政变并开始垂帘听政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慈禧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('deng-shichang','邓世昌','qing','[]',NULL,NULL,1849,1,NULL,'year',1894,1,NULL,'year','["军事家"]','清末海军将领，字正卿，广东番禺人，出身水师学堂。任致远舰管带，甲午战争黄海海战中率舰作战，舰沉后与官兵一同殉难；其事迹成为近代海军史的重要记忆。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓世昌"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dorgon','多尔衮','qing','[]',NULL,NULL,1612,1,NULL,'year',1650,1,NULL,'year','["政治家","军事家"]','清初满洲贵族，爱新觉罗氏，努尔哈赤第十四子。皇太极死后拥立顺治帝并摄政，统兵入关、迁都北京，主导清初统一与制度建设；死后曾被追尊，后遭削爵，乾隆朝复爵。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/多尔衮"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fang-congze','方从哲','ming','[]',NULL,NULL,1562,1,NULL,'year',1627,1,NULL,'year','["政治家"]','明末首辅，泰昌朝红丸案关键人物，后被东林党弹劾；红丸案、移宫案处置引发朝臣弹劾，成为晚明党争焦点。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/方从哲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fulin','福临','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·福临，皇太极第九子，清世祖。幼年即位，由多尔衮摄政；1644年清军入关并迁都北京，顺治亲政后整顿政务，确立清朝对中原的统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顺治帝"}]','章皇帝','世祖','清世祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gu-yanwu','顾炎武','ming','[]',NULL,NULL,1613,1,NULL,'year',1682,1,NULL,'year','["思想家"]','明末清初思想家，日知录作者，经世致用代表；长期游历并搜集碑刻、地理资料；《日知录》《天下郡国利病书》体现经世关怀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾炎武"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-hanqing','关汉卿','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["文学家"]','元代戏曲家，号已斋叟，大都人，生平年月有争议。长期活动于杂剧创作与演出圈，与王实甫等交游；《窦娥冤》《救风尘》等剧传世，被后世称为元杂剧代表作家。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关汉卿"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hai-rui','海瑞','ming','[]',NULL,NULL,1514,1,NULL,'year',1587,1,NULL,'year','["政治家"]','明代官员，字汝贤，号刚峰，琼山人。嘉靖年间任职地方，因上《治安疏》直谏世宗而下狱；后历任地方官，推行清丈、整饬吏治，以刚直敢言著称。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/海瑞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-liner','韩林儿','song-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,1366,1,NULL,'year','["皇帝"]','韩山童之子，号小明王。1351年韩山童谋起事被杀，刘福通等继续领导红巾军；1355年在亳州迎立韩林儿为帝，国号宋、年号龙凤，以汉室后裔和弥勒信仰联结反元力量。政权后迁汴梁、安丰，1363年安丰失守后依附朱元璋，1366年渡江途中溺亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩林儿"}]',NULL,NULL,'小明王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hongli','弘历','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·弘历，清高宗，雍正帝第四子。乾隆朝平定准噶尔、回部等地，编纂《四库全书》；在位六十年后禅位，仍以太上皇训政至1799年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乾隆帝"}]','纯皇帝','高宗','清高宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-taiji','皇太极','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','努尔哈赤第八子，1626年父死后被推举为汗，继承后金及八旗军政组织。逐步削弱其他贝勒权力，扩展对蒙古、朝鲜的控制，并吸收汉军及明朝降官；1635年定族名满洲，1636年在盛京称帝、改国号清。清承续后金政权，皇太极于1643年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皇太极"},{"label":"《清史稿·朝鲜列传》：天聪十年改元崇德、国号大清","url":"https://db.history.go.kr/item/compareViewer.do?levelId=jo_024_0010_0020_0130"}]','文皇帝','太宗','清太宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huang-zongxi','黄宗羲','ming','[]',NULL,NULL,1610,1,NULL,'year',1695,1,NULL,'year','["思想家"]','明末清初思想家，明夷待访录作者，批判君主专制；《明夷待访录》提出限制君权、学校议政等主张，后世常视为早期政治批判著作。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/黄宗羲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('irinchibal','懿璘质班','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','懿璘质班，元宁宗，元明宗幼子。1332年由权臣拥立时年仅七岁，在位约两个月便病逝；随后元廷迎立其异母兄妥懽帖睦尔。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元宁宗"}]','冲圣嗣孝皇帝','宁宗','元宁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xiaolan','纪晓岚','qing','[]',NULL,NULL,1724,1,NULL,'year',1805,1,NULL,'year','["文学家","政治家"]','清代学者，四库全书总纂官，阅微草堂笔记作者；奉命主持《四库全书》编纂，另著笔记小说《阅微草堂笔记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/纪晓岚"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kang-youwei','康有为','qing','[]',NULL,NULL,1858,1,NULL,'year',1927,1,NULL,'year','["政治家","思想家"]','晚清思想家、政治人物，初名祖诒，字广厦，广东南海人。甲午战后发起公车上书，组织强学会并推动维新变法；戊戌政变后流亡海外，晚年仍主张保皇。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/康有为"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('khayishan','海山','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','海山，元武宗，长期在北方统兵，元成宗去世后在军队与蒙古宗王支持下即位。他以封赏和扩张官僚体系巩固新政权，并与弟爱育黎拔力八达约定兄终弟及；其朝财政开支扩大，纸币贬值加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元武宗"}]','仁惠宣孝皇帝','武宗','元武宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('khoshila','和世㻋','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','和世㻋，元明宗，元武宗长子，曾长期流寓漠北。1328年在上都即位，次年与弟图帖睦尔会合并恢复兄弟继位安排；不久在赴大都途中去世，史籍记其死于宴会之后，死因说法不一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/和世㻋"}]','翼献景孝皇帝','明宗','元明宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lan-yu','蓝玉','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,1393,1,NULL,'year','["军事家"]','明初大将，捕鱼儿海大破北元，后涉党案被诛；洪武二十一年捕鱼儿海战俘获北元皇子与大量军民，后因蓝玉案被杀并株连多人。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蓝玉"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-hongzhang','李鸿章','qing','[]',NULL,NULL,1823,1,NULL,'year',1901,1,NULL,'year','["政治家","军事家"]','晚清政治家、外交家，字少荃，安徽合肥人。创办淮军并参与洋务运动，任直隶总督、北洋大臣；代表清政府办理多项外交事务并签订《马关条约》《辛丑条约》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李鸿章"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shizhen','李时珍','ming','[]',NULL,NULL,1518,1,NULL,'year',1593,1,NULL,'year','["医学家"]','明代医药学家，字东璧，号濒湖，蕲州人。长期搜集药物与民间方剂，考订历代本草，历时约二十七年编成《本草纲目》，系统记载药物、产地与用法。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李时珍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xuanshi','李选侍','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,1627,1,NULL,'year','["后妃"]','明光宗宠妃，光宗死后据乾清宫不肯迁出，引发移宫案；朝臣要求她迁出乾清宫保护皇长子，移宫案成为泰昌、天启之际政争之一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李选侍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liang-qichao','梁启超','qing','[]',NULL,NULL,1873,1,NULL,'year',1929,1,NULL,'year','["政治家","思想家"]','晚清思想家、政治家、新闻人，字卓如，号任公，广东新会人。师从康有为并参与戊戌变法，流亡期间创办报刊、倡导立宪与新民思想；回国后转向学术研究，著述丰富。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁启超"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-zexu','林则徐','qing','[]',NULL,NULL,1785,1,NULL,'year',1850,1,NULL,'year','["政治家"]','清代政治家，字元抚，福建侯官人。道光年间任湖广总督、钦差大臣，赴广东查禁鸦片并主持虎门销烟；鸦片战争后被贬，后参与西北边防与新疆治理。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/林则徐"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-futong','刘福通','song-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,1363,1,NULL,'year','["起义领袖"]','红巾军首领，拥立韩林儿为小明王，三路北伐；1363年安丰之战战死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘福通"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ji','刘基','ming','[]',NULL,NULL,1311,1,NULL,'year',1375,1,NULL,'year','["政治家","军事家"]','明初政治家、文学家，字伯温，浙江青田人。元末出仕后归附朱元璋，参与谋划统一战争及建国制度；洪武年间封诚意伯，著有《郁离子》及诗文集。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘基"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ming-sheng','明升','xia-ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,1371,1,NULL,'year','["皇帝"]','明玉珍之子，父死后于1366年继位为夏主。1371年明军攻入重庆，明升出降，明夏亡；后被迁往高丽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明升"}]',NULL,NULL,'明夏帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ming-yuzhen','明玉珍','xia-ming','[]',NULL,NULL,1329,1,NULL,'year',1366,1,NULL,'year','["皇帝"]','随州人，初聚乡里自保，后归附徐寿辉并任元帅。1357年乘势攻取重庆，逐步据有四川大部；1362年在重庆称帝，国号夏，建元天统。建置官署、国子监并开科取士，赋税取十分之一。1366年病逝，谥钦文昭武皇帝、庙号太祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明玉珍"}]','钦文昭武皇帝','太祖','明夏太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('minning','旻宁','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·旻宁，嘉庆帝次子，清宣宗。道光朝面对鸦片输入与边疆、财政问题，1839年命林则徐禁烟；鸦片战争失败后签订《南京条约》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/道光帝"}]','成皇帝','宣宗','清宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('nurhaci','努尔哈赤','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','建州女真人，塔克世之子。1583年父祖在明军征战中被杀后，以遗留部众起兵，逐步兼并建州各部，再向海西女真扩张；通过八旗组织整合军队与人口。1616年在赫图阿拉称汗，国号金，史称后金。此后攻明并夺取辽东，1626年宁远战败后病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/努尔哈赤"}]','武皇帝','太祖','清太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('puyi','溥仪','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·溥仪，道光帝曾孙、光绪帝侄子，清朝末代皇帝。1908年即位，1912年清帝退位，结束清朝统治与中国帝制；后曾任满洲国执政、皇帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/溥仪"},{"label":"吉林省地方志：溥仪（1906～1967）","url":"https://dfz.jl.gov.cn/zsjl/201112/t20111211_5216717.html"}]',NULL,NULL,'清逊帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-jiguang','戚继光','ming','[]',NULL,NULL,1528,1,NULL,'year',1588,1,NULL,'year','["军事家"]','明代抗倭名将，组建戚家军，平定东南倭患；在浙江、福建训练戚家军抗倭，后转守蓟州；著有《纪效新书》《练兵实纪》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/戚继光"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ragibagh','阿速吉八','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','阿速吉八，元天顺帝，也孙铁木儿之子。泰定帝去世后，他在上都由权臣倒剌沙拥立；同年，支持图帖睦尔的势力在大都发动政变并赢得两都之战，阿速吉八败亡，在位仅数周。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阿速吉八"}]',NULL,NULL,'元天顺帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shidebala','硕德八剌','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','硕德八剌，元英宗，元仁宗之子。即位后在拜住辅佐下推行以儒家制度整顿朝政的改革，试图削弱权臣势力；1323年南坡之变中被铁失等人弑杀，改革随之中断。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元英宗"}]','睿圣文孝皇帝','英宗','元英宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-yat-sen','孙中山','roc','[]',NULL,NULL,1866,1,NULL,'year',1925,1,NULL,'year','["政治家"]','广东香山人，早年学医，1894年组织兴中会，推动反清革命；1905年在东京建立同盟会，提出三民主义，联络各地革命力量。1911年武昌起义后各省相继独立，他回国后获省代表推举，1912年1月1日在南京就任中华民国临时大总统。清帝退位后让位于袁世凯，后来继续组织政党与革命活动。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙中山"},{"label":"孙中山故居纪念馆：生平","url":"https://www.sunyat-sen.org/index.php/portal/list/index.html?id=226"}]',NULL,NULL,'临时大总统','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tan-sitong','谭嗣同','qing','[]',NULL,NULL,1865,1,NULL,'year',1898,1,NULL,'year','["政治家","思想家"]','戊戌维新人物，变法失败后遇害，列为戊戌六君子；变法失败后拒绝出逃，1898年在北京遇害；《仁学》批判旧制度与纲常。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谭嗣同"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tang-yin','唐寅','ming','[]',NULL,NULL,1470,1,NULL,'year',1524,1,NULL,'year','["画家","诗人"]','明代吴门画派代表，江南四大才子之一，桃花庵歌作者；科场案后放弃仕进，以卖画为生；与沈周、文徵明、仇英并称吴门四家。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐寅"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('temur','铁穆耳','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','铁穆耳，元成宗，忽必烈之孙。即位后确认忽必烈以来的制度与对外和议，暂停大规模征战，并处理西北诸王与元廷的冲突；在位后期健康恶化且未明确继承人，死后发生皇位继承争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元成宗"}]','钦明广孝皇帝','成宗','元成宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('togon-temur','妥懽帖睦尔','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','妥懽帖睦尔，元顺帝，元朝在中原的末代皇帝。其长期在位期间朝廷屡受权臣与派系斗争影响，黄河水患、财政危机及红巾军起义相继爆发；1368年明军攻入大都，他北走上都，元廷退居漠北。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元顺帝"},{"label":"《明史》卷二·本纪第二：闰七月丙寅克通州，元帝趋上都","url":"https://zh.wikisource.org/wiki/明史/卷2"},{"label":"中国历代朔闰表：1368年农历闰七月及公历换算","url":"https://ytliu0.github.io/ChineseCalendar/table_period_chinese.html?period=ming"}]','顺帝','惠宗','元惠宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('togus-temur','脱古思帖木儿','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','北元末主天元帝，1388年捕鱼儿海之战后为也速迭儿所杀，北元终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/脱古思帖木儿"}]',NULL,NULL,'天元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tugh-temur','图帖睦尔','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','图帖睦尔，元文宗，元武宗之子。两都之战中获胜后即位，曾让位于兄长和世㻋；和世㻋去世后复位。其朝设奎章阁、召集文臣编修典籍，皇位反复更替与权臣斗争仍持续。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元文宗"}]','圣明元孝皇帝','文宗','元文宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-yangming','王阳明','ming','[]',NULL,NULL,1472,1,NULL,'year',1529,1,NULL,'year','["思想家","军事家"]','明代心学集大成者，提出知行合一，平宁王之乱；平定宁王之乱后在江西、广西任事并讲学，弟子整理其说形成阳明学派。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王阳明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-zhongxian','魏忠贤','ming','[]',NULL,NULL,1568,1,NULL,'year',1627,1,NULL,'year','["政治家"]','明末权阉，天启朝专权，东林党争对手，后自缢；他控制东厂并打击东林党人，崇祯即位后失势，在逮捕途中自缢。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏忠贤"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-guangqi','徐光启','ming','[]',NULL,NULL,1562,1,NULL,'year',1633,1,NULL,'year','["科学家","政治家"]','明代科学家，与利玛窦合译几何原本，主持历法改革；他参与翻译《几何原本》前六卷，并主持编修《崇祯历书》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐光启"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-shouhui','徐寿辉','song-xu','[]',NULL,NULL,1320,1,NULL,'year',1360,1,NULL,'year','["皇帝"]','罗田人，元末红巾军首领。1351年在蕲水起事称帝，以蕲水为都，后迁汉阳；部众一度扩展至湖广、江西等地，政权称宋，史籍亦称天完。陈友谅掌握军政后挟其东下，1360年在采石被杀。明玉珍后来追谥应天启运献武皇帝、庙号世宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐寿辉"}]','应天启运献武皇帝','世宗','徐宋世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xu-xiake','徐霞客','ming','[]',NULL,NULL,1587,1,NULL,'year',1641,1,NULL,'year','["地理学家"]','明代地理学家、旅行家，名弘祖，字振之，南直隶江阴人。自青年起多次远游，考察山川、洞穴与水系，行旅日记由后人整理为《徐霞客游记》，兼具地理观察与文学价值。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/徐霞客"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xuanye','玄烨','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·玄烨，顺治帝第三子，清圣祖。亲政后平定三藩、统一台湾，抗击准噶尔并签订《尼布楚条约》，康熙朝国势与疆域进一步发展。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/康熙帝"}]','仁皇帝','圣祖','清圣祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-song','严嵩','ming','[]',NULL,NULL,1480,1,NULL,'year',1567,1,NULL,'year','["政治家"]','嘉靖朝权相，专擅朝政二十年，后遭徐阶等弹劾倒台；徐阶联合言官促成弹劾，严嵩失势后家产被籍没，晚年贫困。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/严嵩"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yeshuntuemur','也孙铁木儿','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','也孙铁木儿，元泰定帝，元武宗之侄，在大都与上都政治势力支持下即位。其朝以稳固蒙古宗王与勋贵为要务；1328年去世后，权臣拥立其子阿速吉八，随即引发两都之战。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元泰定帝"}]',NULL,NULL,'元泰定帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-xin','奕訢','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','恭亲王，与慈禧等发动辛酉政变，参与晚清政务；主持总理各国事务衙门，推动同文馆与近代军工建设，参与洋务运动。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/恭親王"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yinzhen','胤禛','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·胤禛，康熙帝第四子，清世宗。即位后整顿财政，推行摊丁入亩、耗羡归公等政策，实行改土归流并设军机处，加强中央集权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/雍正帝"}]','宪皇帝','世宗','清世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yizhu','奕詝','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·奕詝，道光帝第四子，清文宗。咸丰朝爆发太平天国运动，清廷又在第二次鸦片战争中战败；英法联军攻入北京后，他避居热河并于1861年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/咸丰帝"}]','显皇帝','文宗','清文宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yongyan','颙琰','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·颙琰，乾隆帝第十五子，清仁宗。亲政后诛和珅，镇压白莲教起义；其后清廷财政、吏治与边防问题逐渐加重。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/嘉庆帝"}]','睿皇帝','仁宗','清仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yu-qian','于谦','ming','[]',NULL,NULL,1398,1,NULL,'year',1457,2,NULL,'month','["政治家","军事家"]','明代政治家、军事家，字廷益，钱塘人。土木堡之变后主持北京防务，组织军民击退瓦剌军并稳定明廷；英宗复辟后以谋逆罪被杀，后获平反，谥忠肃。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/于谦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-chonghuan','袁崇焕','ming','[]',NULL,NULL,1584,1,NULL,'year',1630,1,NULL,'year','["军事家"]','明末督师，宁远大捷、宁锦大捷，后被崇祯冤杀；崇祯帝因反间传闻将其下狱处死，后经平反追谥襄愍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁崇焕"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zaichun','载淳','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·载淳，咸丰帝之子，清穆宗。幼年即位，由慈安太后与慈禧太后垂帘听政；同治朝平定太平天国等内乱，实行洋务，1875年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/同治帝"}]','毅皇帝','穆宗','清穆宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zaitian','载湉','qing','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','爱新觉罗·载湉，醇亲王奕譞之子，清德宗。亲政后支持康有为等推行戊戌变法；庚子事变后清廷推进新政，1908年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/光绪帝"}]','景皇帝','德宗','清德宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zeng-guofan','曾国藩','qing','[]',NULL,NULL,1811,1,NULL,'year',1872,1,NULL,'year','["政治家","军事家"]','晚清政治家、军事统帅，初名子城，字伯涵，湖南湘乡人。奉命在湖南编练湘军，镇压太平天国；历任两江总督等职，推动洋务事业，家书与文集广泛流传。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曾国藩"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-juzheng','张居正','ming','[]',NULL,NULL,1525,1,NULL,'year',1582,1,NULL,'year','["政治家"]','明神宗首辅，推行考成法、一条鞭法等改革，史称万历中兴；万历初推行考成法、清丈土地与一条鞭法；死后被夺谥籍产，天启年间复名。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张居正"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-shicheng','张士诚','zhou-zhang','[]',NULL,NULL,1321,1,NULL,'year',1367,1,NULL,'year','["皇帝"]','泰州盐贩，1353年起兵反元，次年在高邮称诚王、国号周，建元天祐。1356年据平江（今苏州）并以之为中心经营江南，1363年称吴王。朱元璋军围攻平江近一年，城破后张士诚被俘，政权于1367年覆亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张士诚"}]',NULL,NULL,'诚王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-guifei','郑贵妃','ming','[]',NULL,NULL,1565,1,NULL,'year',1630,1,NULL,'year','["后妃"]','万历帝宠妃，梃击案牵连其党，国本之争核心人物；朱常洵封福王后国本之争暂息；郑贵妃与梃击案的关联说法不一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑贵妃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-he','郑和','ming','[]',NULL,NULL,1371,1,NULL,'year',1433,1,NULL,'year','["军事家"]','明代航海家，永乐朝率船队七下西洋，沟通中外；船队七下西洋，开展外交、贸易往来，航迹抵达印度洋与东非沿岸。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑和"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-changluo','朱常洛','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱翊钧长子，长期受册立之争影响，1620年继位。其即位后调整部分父朝旧政，却在位仅约一个月便病逝；围绕其服用红丸及死因的争议成为“红丸案”，由子朱由校继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/明光宗"}]','贞皇帝','光宗','明光宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-di','朱棣','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱元璋第四子，初封燕王，驻守北平。建文帝削藩后起兵，历经靖难之役攻入南京并即位；在位期间迁都北京、经营北方边防，派郑和多次下西洋，并编修《永乐大典》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱棣"}]','文皇帝','成祖','明成祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-gaochi','朱高炽','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱棣长子，长期以太子身份留守北京并监国，1424年继位。其即位后调整永乐时期部分政策，起用士人、减轻刑狱与赋役，力图休养生息；在位不足一年，由子朱瞻基继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱高炽"}]','昭皇帝','仁宗','明仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-houcong','朱厚熜','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','兴献王朱祐杬之子，朱厚照无嗣后由宗室入继大统。即位初年围绕生父尊号爆发“大礼议”，其后长期居西苑修道、以严嵩等人理政；在位期间遭遇倭寇侵扰和俺答汗兵临北京的庚戌之变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱厚熜"}]','肃皇帝','世宗','明世宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-houzhao','朱厚照','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱祐樘长子，十五岁即位。其在位时宠信宦官刘瑾，后亲自出巡并以“威武大将军”等名号活动；1519年宁王朱宸濠叛乱被平定，朱厚照次年无嗣去世，由堂弟朱厚熜入继。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱厚照"}]','毅皇帝','武宗','明武宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-jianshen','朱见深','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱祁镇长子，曾在土木堡之变后被立为太子，父亲复位后恢复储位，1464年即位。其在位时平反于谦冤案、恢复景泰帝名号，同时宠信万贵妃并设西厂；晚年由子朱祐樘继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱见深"}]','纯皇帝','宪宗','明宪宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-qiyu','朱祁钰','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱瞻基次子、朱祁镇之弟。土木堡之变后，群臣拥立其为帝以稳定局势；他组织北京保卫战、任用于谦等人击退瓦剌，后改立太子。1457年朱祁镇复位，朱祁钰不久去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱祁钰"}]','景皇帝','代宗','明代宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-qizhen','朱祁镇','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱瞻基长子，先后两度在位（1435—1449、1457—1464）。首次在位时宦官王振权势上升，1449年亲征瓦剌并在土木堡被俘；弟朱祁钰继位后，他被迎回幽居，1457年经夺门之变复位，随后处死于谦等人。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱祁镇"}]','睿皇帝','英宗','明英宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yihai','朱以海','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','鲁监国，弘光亡后监国于绍兴，与隆武、永历并立；后入海，1653年去监国号。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱以海"}]',NULL,NULL,'鲁监国','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yiming','朱翊钧','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱载坖之子，十岁即位，初由李太后与张居正辅政。张居正改革推动整顿吏治、清丈田地与赋税改革；亲政后，明军平定宁夏、播州并援朝抗倭，后期皇帝长期不理朝政，党争与财政危机加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱翊钧"}]','显皇帝','神宗','明神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youcheng','朱祐樘','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱见深之子，1487年继位。其在位时整顿吏治、减轻部分赋役，任用王恕等官员，政治相对稳定，后世称“弘治中兴”；他长期专宠张皇后，死后由子朱厚照继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱祐樘"}]','达皇帝','孝宗','明孝宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youjian','朱由检','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱常洛第五子、朱由校之弟，1627年即位。其勤于政务但面对后金战争、灾荒、财政枯竭与农民起义，内外交困；李自成军攻入北京后，朱由检于1644年自缢，明朝在北京的统治结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/崇祯帝"}]','毅皇帝','思宗','明思宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youjiao','朱由校','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱常洛长子，十六岁继位。其在位时魏忠贤与客氏势力扩张，东林党争及辽东战事持续；皇帝本人喜好木作，故后世有“木匠皇帝”之称。1627年无子去世，由弟朱由检继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱由校"}]','哲皇帝','熹宗','明熹宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-youlang','朱由榔','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','明神宗之孙、桂王朱常瀛之子。隆武政权覆亡后，1646年获丁魁楚、瞿式耜等拥立，在肇庆先监国、后称帝，年号永历，与广州绍武政权及鲁监国并存。依靠西南地方军队与大西军余部延续统治，清军进逼后流亡缅甸，1662年被交给吴三桂，随后在昆明被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/永历帝"}]',NULL,NULL,'永历帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yousong','朱由崧','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','明神宗之孙、福王朱常洵之子。1641年洛阳被李自成军攻陷、父亲被杀后逃往淮安。1644年崇祯帝死，马士英及江北诸将支持他在南京即位，年号弘光，延续明朝。朝廷内部党争及军镇矛盾持续，1645年南京失守后被清军俘获，1646年被处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/弘光帝"}]',NULL,NULL,'弘光帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yuanzhang','朱元璋','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','濠州钟离人，曾为僧，1352年参加郭子兴领导的红巾军，后自行招募军队。1356年据集庆，改为应天府；1363年在鄱阳湖击败陈友谅，1364年称吴王，1367年灭张士诚并遣军北伐。1368年在应天称帝，国号明，随后攻取大都。即位后整顿赋役与户籍，强化皇权，废除丞相制度。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱元璋"},{"label":"《明史》卷一·太祖本纪（吴二年即皇帝位、定国号大明）","url":"https://zh.wikisource.org/zh-hans/明史/卷1"}]','高皇帝','太祖','明太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yujian','朱聿键','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','明太祖后裔，原封唐王，曾因擅自领兵勤王被废爵囚禁，弘光时获释。1645年南京失守后，在郑鸿逵护送下进入福建，获郑芝龙等拥立，在福州称帝，年号隆武。军队与财政受郑氏影响，1646年郑芝龙撤防降清，朱聿键出走汀州，被清军俘获后遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/隆武帝"},{"label":"《元史·顺帝纪》（维基文库）","url":"https://zh.wikisource.org/wiki/元史/卷046"},{"label":"《明史·唐王聿键传》（维基文库）","url":"https://zh.wikisource.org/wiki/明史/卷118"}]',NULL,NULL,'隆武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yunwen','朱允炆','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱元璋之孙、皇太子朱标之子，1398年承祖父之位。建文帝推行削藩，引发叔父燕王朱棣起兵的靖难之役；1402年南京失守后下落不明，朱棣即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/建文帝"}]',NULL,NULL,'建文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-yuyue','朱聿鐭','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','绍武帝，隆武之弟，1646年广州称帝，与肇庆永历并立，旋为清军所破。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/绍武帝"}]',NULL,NULL,'绍武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-zaihou','朱载坖','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱厚熜第三子，1567年继位。其在位时起用高拱、张居正等人调整政务，隆庆年间开放海贸并与蒙古俺答部议和互市；死后由十岁的儿子朱翊钧继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱载坖"}]','庄皇帝','穆宗','明穆宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhu-zhanji','朱瞻基','ming','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','朱高炽长子，自幼随祖父朱棣参与北征，1425年继位。其在位时与“三杨”等大臣共同理政，延续宽政并整顿边务，形成所谓“仁宣之治”；死后由子朱祁镇继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱瞻基"}]','章皇帝','宣宗','明宣宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zuo-zongtang','左宗棠','qing','[]',NULL,NULL,1812,1,NULL,'year',1885,1,NULL,'year','["政治家","军事家"]','晚清政治家、军事统帅，字季高，湖南湘阴人。曾参与镇压太平天国与捻军，任陕甘总督后率军收复新疆；倡办福州船政局等洋务事业，晚年任军机大臣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/左宗棠"}]',NULL,NULL,NULL,'[]');
